using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;
class Regression {
 static List<string> results=new List<string>();
 static void Pass(string label,bool yes){if(!yes)throw new Exception("FAIL: "+label);results.Add("PASS: "+label);}
 static object Call(Type type,string method,params object[] args){return type.GetMethod(method,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public).Invoke(null,args);}
 static string Token(string email){Func<string,string> e=x=>Convert.ToBase64String(Encoding.UTF8.GetBytes(x)).TrimEnd('=').Replace('+','-').Replace('/','_');return e("{\"alg\":\"none\"}")+"."+e("{\"email\":\""+email+"\",\"exp\":4102444800}")+".test-only";}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);try{
  var store=new ProfileStore(Path.Combine(root,"profiles"));store.State.SharedStatePath=Path.Combine(root,"common");Directory.CreateDirectory(store.State.SharedStatePath);var a=store.State.Profiles[0];var b=store.State.Profiles[1];string desktop=Path.Combine(store.Root,a.Folder,"desktop");
  var graph=new[]{new NativeProcessRow{Id=101,Name="ChatGPT.exe",CommandLine="ChatGPT.exe"},new NativeProcessRow{Id=102,ParentId=101,Name="ChatGPT.exe",CommandLine="ChatGPT.exe --type=crashpad-handler --user-data-dir=\""+desktop+"\""},new NativeProcessRow{Id=103,ParentId=101,Name="ChatGPT.exe",CommandLine="ChatGPT.exe --type=gpu-process"}};
  var classified=NativeApp.Classify(store,graph);Pass("desktop root inherits profile from child startup data",classified.Count==1&&classified[0].Id==101&&classified[0].ProfileId==a.Id);
  Pass("orphan crash reporter does not permanently block switching",NativeApp.Classify(store,new[]{graph[1]}).Count==0);
  Pass("standalone Codex account session still blocks",NativeApp.Classify(store,new[]{new NativeProcessRow{Id=104,Name="codex.exe",CommandLine="codex app-server"}}).Count==1);
  Pass("unreadable desktop command line fails closed",NativeApp.Classify(store,new[]{new NativeProcessRow{Id=105,Name="ChatGPT.exe",CommandLine=""}}).Count==1);
  var before=NativeApp.Running(store);if(before.Count>0){bool blocked=false;try{NativeApp.Launch(store,a);}catch{blocked=true;}Pass("real active desktop prevents production profile launch",blocked&&!Directory.Exists(Path.Combine(store.Root,a.Folder)));}
  var startA=NativeApp.BuildStartInfo(store,a,"test.exe");var startB=NativeApp.BuildStartInfo(store,b,"test.exe");Pass("profile homes and browser sessions separate",startA.EnvironmentVariables["CODEX_HOME"]!=startB.EnvironmentVariables["CODEX_HOME"]&&startA.EnvironmentVariables["CODEX_ELECTRON_USER_DATA_PATH"]!=startB.EnvironmentVariables["CODEX_ELECTRON_USER_DATA_PATH"]);Pass("all launch plans use identical shared database root",startA.EnvironmentVariables["CODEX_SQLITE_HOME"]==startB.EnvironmentVariables["CODEX_SQLITE_HOME"]);
  string home=Path.Combine(store.Root,a.Folder,"codex");Directory.CreateDirectory(home);string auth=Path.Combine(home,"auth.json");FeatureJson.Write(auth,new{tokens=new{id_token=Token("one@invalid.example"),account_id="workspace-one"}});var first=AccountService.Cached(store,a);FeatureJson.Write(auth,new{tokens=new{id_token=Token("two@invalid.example"),account_id="workspace-two"}});var second=AccountService.Cached(store,a);Pass("credential changes invalidate verified identity stamp",first.CredentialStamp!=second.CredentialStamp&&second.Email=="two@invalid.example"&&!second.Verified);a.ExpectedEmail="one@invalid.example";AccountService.ApplyExpected(second,a);Pass("wrong saved identity blocks configured profile",second.Mismatch);
  store.Edit(b.Id,p=>p.Favorite=true);Pass("favorites reorder without losing stable folders",store.Ordered()[0].Id==b.Id);store.Move(a.Id,b.Id);Pass("drag reorder across groups persists",new ProfileStore(store.Root).Ordered()[0].Id==a.Id);store.Rename(a.Id,"QA renamed");Pass("rename preserves account data folder",store.State.Profiles.Single(x=>x.Id==a.Id).Folder==a.Folder);store.Remove(a.Id);store.Restore(a.Id);Pass("remove/restore retains saved login",File.Exists(auth));
  File.Copy(Path.Combine(root,"fixtures","state_5.sqlite"),Path.Combine(store.State.SharedStatePath,"state_5.sqlite"));File.Copy(Path.Combine(root,"fixtures","thread_history_1.sqlite"),Path.Combine(store.State.SharedStatePath,"thread_history_1.sqlite"));File.Copy(Path.Combine(root,"fixtures","state_4.sqlite"),Path.Combine(store.State.SharedStatePath,"state_4.sqlite"));Pass("history counts use current schema only",SharedState.Count(store.State.SharedStatePath,"threads")==2);File.Delete(Path.Combine(store.State.SharedStatePath,"state_4.sqlite"));
  string snapshot=(string)Call(typeof(BackupService),"CreateCore",store);BackupService.Validate(store,snapshot);Pass("snapshot validates and excludes credentials",!Directory.GetFiles(snapshot,"auth*",SearchOption.AllDirectories).Any());string oldPath=store.State.SharedStatePath;store.State.SharedStatePath=Path.Combine(root,"wrong-store");bool wrong=false;try{BackupService.Validate(store,snapshot);}catch{wrong=true;}store.State.SharedStatePath=oldPath;Pass("backup from a different shared store rejected",wrong);
  string backupDb=Path.Combine(snapshot,"state_5.sqlite");byte[] original=File.ReadAllBytes(backupDb);File.AppendAllText(backupDb,"tamper");bool tampered=false;try{BackupService.Validate(store,snapshot);}catch{tampered=true;}Pass("tampered backup rejected",tampered);File.WriteAllBytes(backupDb,original);
  // Force failure on the first file, after recovery sidecars have been moved.
  File.Copy(Path.Combine(root,"fixtures","wal-state.sqlite"),Path.Combine(oldPath,"state_5.sqlite"),true);File.Copy(Path.Combine(root,"fixtures","wal-state.sqlite-wal"),Path.Combine(oldPath,"state_5.sqlite-wal"),true);Pass("WAL fixture includes committed newer data",SharedState.Count(oldPath,"threads")==3);
  var fault=typeof(BackupService).GetField("RestoreFault",BindingFlags.Static|BindingFlags.NonPublic);fault.SetValue(null,(Action<string>)(name=>{throw new IOException("Injected replacement failure");}));bool failed=false;try{Call(typeof(BackupService),"RestoreFiles",store,snapshot,(Action)(()=>{}));}catch{failed=true;}finally{fault.SetValue(null,null);}Pass("interrupted restore reports failure",failed);Pass("interrupted first database preserves WAL-committed data",SharedState.Count(oldPath,"threads")==3);SharedState.CheckIntegrity(Path.Combine(oldPath,"state_5.sqlite"));
  int interruptedFiles=0;fault.SetValue(null,(Action<string>)(name=>{if(++interruptedFiles==2)throw new IOException("Injected second-file failure");}));failed=false;try{Call(typeof(BackupService),"RestoreFiles",store,snapshot,(Action)(()=>{}));}catch{failed=true;}finally{fault.SetValue(null,null);}Pass("partial multi-database restore recovers every touched file",failed&&SharedState.Count(oldPath,"threads")==3);
  Call(typeof(BackupService),"RestoreFiles",store,snapshot,(Action)(()=>{}));Pass("successful restore returns snapshot contents",SharedState.Count(oldPath,"threads")==2);Pass("pre-restore snapshots retained",BackupService.List(store).Length>=3);
  string diagnostic=Path.Combine(root,"diagnostics.json");DiagnosticService.Export(store,diagnostic);string report=File.ReadAllText(diagnostic);Pass("diagnostics exclude identity/token/path/profile name",!report.Contains("invalid.example")&&!report.Contains("workspace-two")&&!report.Contains("id_token")&&!report.Contains("QA renamed")&&!report.Contains(store.Root));
  bool unconfigured=false;try{ReleaseService.Check(store);}catch{unconfigured=true;}Pass("unconfigured updates fail closed",unconfigured);store.State.UpdateManifestUrl="http://invalid.example";store.State.PublisherThumbprint=new string('A',40);bool insecure=false;try{ReleaseService.Check(store);}catch{insecure=true;}Pass("non-HTTPS update rejected before network",insecure);
  Pass("current native compatibility marker found",CompatibilityService.Check().Passed);
  var locked=new System.Threading.ManualResetEvent(false);var locker=new System.Threading.Thread(()=>{using(var file=new FileStream(Path.Combine(store.Root,"profiles.json"),FileMode.Open,FileAccess.Read,FileShare.None)){locked.Set();System.Threading.Thread.Sleep(250);}});locker.Start();locked.WaitOne();store.Rename(a.Id,"After temporary lock");locker.Join();Pass("profile save recovers from transient file lock",new ProfileStore(store.Root).State.Profiles.Single(x=>x.Id==a.Id).Name=="After temporary lock");
 }catch(Exception e){results.Add(e.ToString());Environment.ExitCode=1;}finally{File.WriteAllLines(Path.Combine(root,"regression-results.txt"),results);foreach(string line in results)Console.WriteLine(line);}}
}
